# Installs the Python package k13s, generated by JGraph's mcc:
#     python -m pip install .
# from the folder this file is in.

try:
    from setuptools import setup
except ImportError:
    raise EnvironmentError("Installation failed. Install setuptools using 'python -m pip install setuptools', then try again.")

if __name__ == '__main__':
    setup(
        name='k13s-R2025b',
        version='25.2',
        description='A Python interface to k13s',
        platforms=['Windows'],
        packages=[
            'k13s'
        ],
        package_data={'k13s': ['*.ctf']},
    )
